// Turkish voice lines (class C). Native script, written from the beat in beats-*.js; never translated from English.
// Group: story-hoods-01-10. beatId -> [{ t, j (joke), spk (only when it differs from the beat) }]. No logic.
Object.assign(P.DLG.tr, {
  "H01b": [{ t: "Hat kapalı! Sarı çizginin gerisine geçin! Bilet kontrolü var!", ok: 1 }],
  "H01i1a": [{ t: "Dürüm masada kaldı. Ustanın bıçağı elimde." }],
  "H01i1b": [{ t: "Bıçağı çok sıkma, Profesör. Bırak ağırlığı işini yapsın." }],
  "H01i2a": [{ t: "Cadde dolu. Kimi koşuyor, kimi kaldırımda sürünüyor. Hepsi bana dönüyor." }],
  "H01i3a": [{ t: "Kafaya vur. Isırılma. Durma. Üç şey, aklımda tutabilirim." }],
  "H01i3b": [{ t: "Eve giden yol bu kalabalığın içinden geçiyor." }],
  "H02b": [{ t: "Merdivenden çekilin! Ağırlıkları salıyorum!", ok: 1 }],
  "H02i1a": [{ t: "Galata merdivenleri. Bir müzisyen, bomboş sokağa çalıyor." }],
  "H02i1b": [{ t: "Şu şarkıyı bir bitireyim. Sonra ben de gideceğim." }],
  "H02i2a": [{ t: "Basamağa bir şey sıçradı. Taşın üstünde köpürüyor." }],
  "H02i3a": [{ t: "Kulenin dibine makara kurmuşlar. Zincirin sesi hiç hayra alamet değil.", ok: 1 }],
  "H02i3b": [{ t: "Karaköy yolu kulenin önünden geçiyor. Önce şu kalabalığı aşmam lazım." }],
  "H03b": [{ t: "Arabaları rampadan indirin! Halatı ben çekerim!", ok: 1 }],
  "H03i1a": [{ t: "Karaköy. Düğün salonunda müzik var, insan sesi yok. Masalarda yarım kalmış tabaklar." }],
  "H03i1b": [{ t: "Umarım arka kapıdan çıkmışlardır." }],
  "H03i2a": [{ t: "Sokağın kedisi peşime takıldı. Adını Paşa koydum." }],
  "H03i2b": [{ t: "Tamam Paşa, sen önden git. Ben de yolu biliyormuş gibi yaparım.", j: 1 }],
  "H03i3a": [{ t: "Dombililer gaz tüplerinin yanında. Biri patlarsa hepsi patlar.", ok: 1 }],
  "H04b": [{ t: "Olta attım! Çekiyorum, çekiyorum!", ok: 1 }],
  "H04i1a": [{ t: "Galata Köprüsü. İki kat: üstte olta ipleri, altta balık lokantaları.", ok: 1 }],
  "H04i2a": [{ t: "Gelme! Balık atarım! Bak, kılçığını da ayıklamam!", j: 1 }],
  "H04i3a": [{ t: "Balığı şimdi zombilere savuruyor. Ben de o tarafa geçebilirsem konuşuruz." }],
  "H04i3b": [{ t: "Aramızda olta ipleri var. Önce şu düğümden kurtulmam lazım." }],
  "H05b": [{ t: "Çapa geliyor, tayfa!", ok: 1 }],
  "H05i1a": [{ t: "Eminönü. Baharat çuvalları, tuzlu hava, balık-ekmek tekneleri.", ok: 1 }],
  "H05i2a": [{ t: "Kaptan Nuri'yi bulalım abi. Yedi yıldır bu teknede beraberiz." }],
  "H05i3a": [{ t: "Güvertede biri var. Kaptan! Biziz!" }],
  "H05i3b": [{ t: "Ses vermedi. Yakından bakalım. Yanındayım." }],
  "H05p1": [{ t: "Baharat çuvalları burnumu yakıyor. Ama ne güzel kokuyor!", ok: 1 }],
  "H05p2": [{ t: "El arabasını itersek çarşıda yol açılır." }],
  "H05p3": [{ t: "Üç çuval yolu kapatmış. Taşırken çıkan tozu soluma, Arda." }],
  "H05p4": [{ t: "Feneri yakabilirsek rıhtımda önümüzü görürüz." }],
  "H06b": [{ t: "Bilet yok, giriş yok!", ok: 1 }],
  "H06i1a": [{ t: "Sirkeci. Saatin altında gidecek yeri kalmamış bir vagon.", ok: 1 }],
  "H06i2a": [{ t: "Yolcu kapıları kilitli. Burada çalışan biri varsa arka yolu bilir.", ok: 1 }],
  "H06i3a": [{ t: "Biletçi kapının arkasında. Önünde zombiler sıra olmuş.", ok: 1 }],
  "H06i3b": [{ t: "Kaan, buradayım. Şu kuyruğun yanından geçelim.", ok: 1 }],
  "H06p1": [{ t: "Bu vagon burada kaldıkça perona çıkamayız.", ok: 1 }],
  "H06p2": [{ t: "Görevliyi gözden kaçırma Arda. Bütün anahtarlar onda.", ok: 1 }],
  "H06p3": [{ t: "Saatle kapı aynı panoya bağlı. Sigortayı bulursam kapıyı açabilirim." }],
  "H06p4": [{ t: "Şu ışıkları yakınca bizi de görürler. Hazır ol.", ok: 1 }],
  "H06p5": [{ t: "Makas ters yöne bakıyor. Kolu ben çekerim, sen raylara bak." }],
  "H06m1": [{ t: "Raydan uzak dur abi. Yanımda kal, birlikte geçeriz." }],
  "H06m2": [{ t: "Görevli kapıyı açacak. Yanından ayrılmayayım." }],
  "H06m3": [{ t: "Babamı o saatin altında beklerdim. Eve dönüşte hep en son vagondan inerdi.", ok: 1 }],
  "H06m4": [{ t: "Eve varınca ilk iş bütün ışıkları yakacağım.", ok: 1 }],
  "H06m5": [{ t: "İşaretli raylardan çık. Yumruğu boşa gidince yanına sokul.", ok: 1 }],
  "H07b": [{ t: "Halıya basma! Üstünden kan geçmiyor!", j: 1 }],
  "H07i1a": [{ t: "Kapalıçarşı. Kemerlerin altında sıcak lambalar, duvarda kilimler.", ok: 1 }],
  "H07i2a": [{ t: "Kepenkte bir not: \"Açmayın.\" Alt kenarı içeri doğru bükülmüş." }],
  "H07i3a": [{ t: "Abi, bunu dışarıdan zorlamışlar. İçerideki saklanıyorsa kapıyı açmayalım." }],
  "H07i3b": [{ t: "İçeriden bir sandalye sürüklendi. Kapıyı tutan biri var. Sessizce uzaklaştık." }],
  "H07p1": [{ t: "Arkamdaki kepenk de indi! Açık bir geçit bulmam lazım." }],
  "H07p2": [{ t: "Arda, şu halı rulosunun arkasına geç. Buradan seni göremezler." }],
  "H07p3": [{ t: "Tezgâhların arkasında bir şey kıpırdıyor. 'Bakmak bedava' diyecek, biliyorum.", ok: 1 }],
  "H07p4": [{ t: "Arda, birbirimizi kaybetmeyelim. Ben şu köşeye bakıyorum." }],
  "H08b": [{ t: "Yem var, yem! Gel, gel! Sen de gel, seni de beslerim!", ok: 1 }],
  "H08i1a": [{ t: "Beyazıt meydanı. Sahaflar, güvercinler ve kapıda 'Bugün kapalı' tabelası.", ok: 1 }],
  "H08i2a": [{ t: "Kuşlar birden havalandı. Dur Kaan, meydanda biri var." }],
  "H08i3a": [{ t: "Güvercinci elini yem torbasına sokuyor. Kuşlar yanına konmuyor." }],
  "H08p1": [{ t: "Kuşlar yine havalandı. Aynı taraftan geliyorlar!" }],
  "H08p2": [{ t: "Kitapçının kapısı aralık abi. İçeri seslenelim mi?" }],
  "H08p3": [{ t: "Şu kitabı ben de almıştım. Benimki de böyle hiç açılmamıştı.", j: 1 }],
  "H08p4": [{ t: "Kuşları ürkütme abi. Bir şey yaklaşınca onlar fark ediyor." }],
  "H09b": [{ t: "Sandığı tut! Altında kalırsın!" }],
  "H09i1a": [{ t: "Kumkapı. Balıklar buzda. Her yerde deniz kokusu.", ok: 1 }],
  "H09i2a": [{ t: "Şu mezecide kaptanla yemek yerdik. Hep aynı masaya otururdu." }],
  "H09i3a": [{ t: "Köşedeki müzisyen aynı birkaç notayı çalıyor. Parmakları hiç durmuyor." }],
  "H09p1": [{ t: "Sandıkların yanında gaz kokusu var. Burada ateş yakma abi." }],
  "H09p2": [{ t: "Buzlar erimiş. Kaçarken bir de kaymayı öğrendim.", j: 1 }],
  "H09p3": [{ t: "Müziğe geliyorlar abi. Şu köşeden uzaklaşalım." }],
  "H09p4": [{ t: "Sahil buradan görünüyor. Doğru yoldayız." }],
  "H10b": [{ t: "Sıraya girin! Flaş yasak, dokunmak yasak, koşmak da yasak.", ok: 1 }],
  "H10i1a": [{ t: "Topkapı Sarayı. Gişe boş. Bilet kuyruğu hâlâ yerinde." }],
  "H10i2a": [{ t: "Saray bu mu abi? Çay ocağı kapalı, simitçi yok.", ok: 1 }],
  "H10i2b": [{ t: "Ben küçükken de önce simit arardım. Sarayı gezmeye gelen tek kişi annemdi.", j: 1 }],
  "H10i3a": [{ t: "Rehber bayrağı kaldırdı. Kaan, sakın soru sorma. Tur uzar.", j: 1 }],
  "H10p1": [{ t: "Bariyere çarpıp özür diledim. İyi değilim abi.", j: 1 }],
  "H10p2": [{ t: "Abi, sıraya girer misin? Girmiyorsun. Tamam, anlaşıldı.", j: 1, ok: 1 }],
  "H10p3": [{ t: "Bariyerler bizi tek sıraya soktu. Sen geç, ben arkandayım." }],
  "H10p4": [{ t: "Yağmur bastırdı. İçerisi kuru ama bilet yok.", ok: 1 }],
});
